select @bc_tu_ngay ngay_bc_tu, @bc_den_ngay ngay_bc_den, @kh_tu_ngay ngay_kh_tu, @kh_den_ngay ngay_kh_den
exec zrpt_O016 @bc_tu_ngay, @bc_den_ngay, @kh_tu_ngay, @kh_den_ngay, @nh_vv1, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
